#42
let o={n:6,work:(xs)=>map((x)=>self.n+x,xs)}
assert(o.work([1,2])==[7,8])
fn fact(n) { if n==0 {return 1}
 n*fact(n-1) }
assert(map(fact,[0,1,5])==[1,1,120])
fn shadow(argv) => map((x)=>argv+x,[1,2])
assert(shadow(9)==[10,11])
let saved=argv
fn invoke(f) => f()
assert(invoke(saved)==["one","中文",""])

